2	declare(strict_types=1);
3	
4	function db(): PDO
5	{
6	    static $pdo = null;
7	    if ($pdo instanceof PDO) {
8	        return $pdo;
9	    }
10	    $c = config('db');
11	    if (!is_array($c)) {
12	        throw new RuntimeException('Database is not configured.');
13	    }
14	    $dsn = 'mysql:host=' . $c['host'] . ';dbname=' . $c['name'] . ';charset=utf8mb4';
15	    $pdo = new PDO($dsn, $c['user'], $c['pass'], [
16	        PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION,
17	        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
18	        PDO::ATTR_EMULATE_PREPARES   => false,
19	    ]);
20	    return $pdo;
21	}
22	
23	/** Read one app_settings value (cached per request). */
24	function setting(string $key, ?string $default = null): ?string
25	{
26	    static $cache = null;
27	    if ($cache === null) {
28	        $cache = [];
29	        try {
30	            foreach (db()->query('SELECT setting_key, setting_value FROM app_settings') as $r) {
31	                $cache[$r['setting_key']] = $r['setting_value'];
32	            }
33	        } catch (Throwable $e) {
34	            $cache = [];
35	        }
36	    }
37	    return array_key_exists($key, $cache) && $cache[$key] !== null ? $cache[$key] : $default;
38	}
39	
40	function set_setting(string $key, string $value): void
41	{
42	    $st = db()->prepare('INSERT INTO app_settings (setting_key, setting_value) VALUES (?, ?)
43	                         ON DUPLICATE KEY UPDATE setting_value = VALUES(setting_value)');
44	    $st->execute([$key, $value]);
45	}
